import fs from 'node:fs';
import {createHash,generateKeyPairSync} from 'node:crypto';
import {signEnvelope,releaseKeySpec,POLICY_FORMAT,STATEMENT_FORMAT} from '../enclave/windows/node/release-channel.mjs';
const dir=new URL('./',import.meta.url);
const keys=Array.from({length:3},()=>generateKeyPairSync('ec',{namedCurve:'prime256v1'}).privateKey);
const policy={format:POLICY_FORMAT,channel:'test',threshold:2,keys:keys.slice(0,2).map(releaseKeySpec),mirrors:['https://mirror.invalid/']};
const statement={format:STATEMENT_FORMAT,channel:'test',version:'1.2.3',issuedAt:new Date().toISOString(),expiresAt:new Date(Date.now()+3600000).toISOString(),file:'enclave-host-1.2.3.zip',sha256:'a'.repeat(64),bytes:1,setup:'EnclaveSetup-1.2.3.exe',setupSha256:'b'.repeat(64),setupBytes:1,manifest:'manifest-1.2.3.json',manifestSha256:'c'.repeat(64),manifestBytes:1};
const valid=signEnvelope(statement,keys.slice(0,2));
const tampered=JSON.parse(valid);tampered.statement=Buffer.from(JSON.stringify({...statement,sha256:'d'.repeat(64)})).toString('base64');
const cases={valid,threshold:signEnvelope(statement,[keys[0]]),foreign:signEnvelope(statement,[keys[2]]),tampered:JSON.stringify(tampered),expired:signEnvelope({...statement,expiresAt:new Date(Date.now()-3600000).toISOString()},keys.slice(0,2)),channel:signEnvelope({...statement,channel:'other'},keys.slice(0,2))};
fs.writeFileSync(new URL('policy.json',dir),JSON.stringify(policy));
for(const [name,value] of Object.entries(cases))fs.writeFileSync(new URL(name+'.json',dir),value);
const source=fs.readFileSync(new URL('../enclave/windows/installer/EnclaveSetup.cs',import.meta.url),'utf8');
const start=source.indexOf('    static class ReleaseChannel');
const end=source.indexOf('    /// <summary>Setup\'s progress:',start);
if(start<0||end<0)throw Error('Cannot isolate verifier');
const body=source.slice(start,end);
const using='using System;using System.Collections;using System.Collections.Generic;using System.Globalization;using System.IO;using System.Net;using System.Security.Cryptography;using System.Text;using System.Text.RegularExpressions;using System.Web.Script.Serialization;\n';
const harness=`public static class Check { public static int Main(string[] args) { var p=ReleaseChannel.LoadPolicy(Path.Combine(args[0],"policy.json")); int passed=0; foreach(var n in new string[]{"valid","threshold","foreign","tampered","expired","channel"}) { bool accepted=false; try { var r=ReleaseChannel.Verify(File.ReadAllText(Path.Combine(args[0],n+".json")),p); accepted=r.Version=="1.2.3"; } catch(Exception) {} bool ok=accepted==(n=="valid"); Console.WriteLine(n+":"+(ok?"PASS":"FAIL")); if(ok)passed++; } return passed==6?0:1; } }`;
fs.writeFileSync(new URL('Check.cs',dir),using+body+harness);
fs.writeFileSync(new URL('source.json',dir),JSON.stringify({verifierSha256:createHash('sha256').update(body).digest('hex'),sourceSha256:createHash('sha256').update(source).digest('hex'),cases:Object.keys(cases)},null,2));
console.log('Prepared six public-only fixtures and isolated C# verifier; no installer actions included.');
